local _, addon = ...
-- Fully qualified addon table paths stay editable in RPTextStudio.
addon.localeData.deDE.generalTexts.CURTSEY = { gruppe = { "Manieren überleben auch die längste Reise.", "Eine höfliche Geste öffnet manche Tür." }, ziel = { "%s, eine höfliche Geste öffnet manche Tür.", "%s: Manieren überleben auch die längste Reise." } }
addon.localeData.deDE.generalTexts.DISAPPOINTED = { gruppe = { "Das hatte ich mir anders vorgestellt.", "Ein Versprechen sollte mehr als Klang besitzen." }, ziel = { "%s, ein Versprechen sollte mehr als Klang besitzen.", "%s: Das hatte ich mir anders vorgestellt." } }
addon.localeData.deDE.generalTexts.DOH = { gruppe = { "Bei allen Ahnen, wie konnte mir das entgehen?", "Meine glänzende Idee kam zu spät." }, ziel = { "%s, meine glänzende Idee kam zu spät.", "%s: Bei allen Ahnen, wie konnte mir das entgehen?" } }
addon.localeData.deDE.generalTexts.DOOM = { gruppe = { "Das klingt nach einem Ende mit wenig Applaus.", "Ich habe ein düsteres Gefühl bei der Sache." }, ziel = { "%s, ich habe ein düsteres Gefühl bei der Sache.", "%s: Das klingt nach einem Ende mit wenig Applaus." } }
addon.localeData.deDE.generalTexts.DROOL = { gruppe = { "Dieser Duft übertrifft jede Verhandlung.", "Wer hat das köstliche Essen versteckt?" }, ziel = { "%s, wer hat das köstliche Essen versteckt?", "%s: Dieser Duft übertrifft jede Verhandlung." } }
addon.localeData.deDE.generalTexts.DUCK = { gruppe = { "Runter mit den Köpfen, sofort!", "Die Fragen stellen wir hinter der nächsten Mauer." }, ziel = { "%s, die Fragen stellen wir hinter der nächsten Mauer.", "%s: Runter mit den Köpfen, sofort!" } }
addon.localeData.deDE.generalTexts.EAT = { gruppe = { "Ein voller Magen macht die Welt freundlicher.", "Von diesem Braten möchte ich noch hören." }, ziel = { "%s, von diesem Braten möchte ich noch hören.", "%s: Ein voller Magen macht die Welt freundlicher." } }
addon.localeData.deDE.generalTexts.EYE = { gruppe = { "Ich behalte die Sache vorsichtshalber im Blick.", "Manche Antworten stehen direkt vor uns." }, ziel = { "%s, manche Antworten stehen direkt vor uns.", "%s: Ich behalte die Sache vorsichtshalber im Blick." } }
addon.localeData.deDE.generalTexts.FAREWELL = { gruppe = { "Mögen Eure Wege sicher und Eure Rastplätze warm sein.", "Wir treffen uns am nächsten Kreuzweg wieder." }, ziel = { "%s, wir treffen uns am nächsten Kreuzweg wieder.", "%s: Mögen Eure Wege sicher und Eure Rastplätze warm sein." } }
addon.localeData.deDE.generalTexts.FEAST = { gruppe = { "Ein gutes Fest braucht hungrige Freunde.", "Heute spart niemand am Nachtisch." }, ziel = { "%s, heute spart niemand am Nachtisch.", "%s: Ein gutes Fest braucht hungrige Freunde." } }
addon.localeData.deDE.generalTexts.FEAR = { gruppe = { "Manche Schatten verdienen keine Neugier.", "Bleibt nahe bei mir. Hier stimmt etwas nicht." }, ziel = { "%s, bleibt nahe bei mir. Hier stimmt etwas nicht.", "%s: Manche Schatten verdienen keine Neugier." } }
addon.localeData.deDE.generalTexts.FIDGET = { gruppe = { "Meine Hände kennen keine Geduld mehr.", "Warten kann erstaunlich anstrengend sein." }, ziel = { "%s, warten kann erstaunlich anstrengend sein.", "%s: Meine Hände kennen keine Geduld mehr." } }
addon.localeData.deDE.generalTexts.FLAP = { gruppe = { "Flügel wären gerade sehr praktisch.", "Vielleicht sollte ich zuerst das Landen lernen." }, ziel = { "%s, vielleicht sollte ich zuerst das Landen lernen.", "%s: Flügel wären gerade sehr praktisch." } }
addon.localeData.deDE.generalTexts.FLEE = { gruppe = { "Rückzug ist eine unterschätzte Kunst!", "Wer länger leben will, läuft jetzt." }, ziel = { "%s, wer länger leben will, läuft jetzt.", "%s: Rückzug ist eine unterschätzte Kunst!" } }
addon.localeData.deDE.generalTexts.FLEX = { gruppe = { "Diese Muskeln wurden nicht beim Lesen erworben.", "Ein wenig Angeberei muss erlaubt sein." }, ziel = { "%s, ein wenig Angeberei muss erlaubt sein.", "%s: Diese Muskeln wurden nicht beim Lesen erworben." } }
addon.localeData.deDE.generalTexts.FLOP = { gruppe = { "Für heute hat die Schwerkraft gewonnen.", "Der Boden hat mich sehr überzeugend eingeladen." }, ziel = { "%s, der Boden hat mich sehr überzeugend eingeladen.", "%s: Für heute hat die Schwerkraft gewonnen." } }
addon.localeData.deDE.generalTexts.FOLLOWME = { gruppe = { "Mir nach, ich kenne wenigstens einen Weg.", "Haltet Euch zusammen, der Pfad ist schmal." }, ziel = { "%s, haltet Euch zusammen, der Pfad ist schmal.", "%s: Mir nach, ich kenne wenigstens einen Weg." } }
addon.localeData.deDE.generalTexts.FOOD = { gruppe = { "Von Mut allein wird man nicht satt.", "Hat jemand ein Stück Brot übrig?" }, ziel = { "%s, hat jemand ein Stück Brot übrig?", "%s: Von Mut allein wird man nicht satt." } }
addon.localeData.deDE.generalTexts.FROWN = { gruppe = { "Das gefällt mir ganz und gar nicht.", "Schlechte Nachrichten verdienen einen langen Blick." }, ziel = { "%s, schlechte Nachrichten verdienen einen langen Blick.", "%s: Das gefällt mir ganz und gar nicht." } }
addon.localeData.deDE.generalTexts.GASP = { gruppe = { "Bei allen Mächten, das kam unerwartet!", "Das muss ich erst einmal begreifen." }, ziel = { "%s, das muss ich erst einmal begreifen.", "%s: Bei allen Mächten, das kam unerwartet!" } }
addon.localeData.deDE.generalTexts.GAZE = { gruppe = { "Manche Dinge verdienen einen zweiten Blick.", "Dort draußen wartet eine ganze Geschichte." }, ziel = { "%s, dort draußen wartet eine ganze Geschichte.", "%s: Manche Dinge verdienen einen zweiten Blick." } }
addon.localeData.deDE.generalTexts.GLAD = { gruppe = { "Heute ist ein guter Tag für ein Wiedersehen.", "Wie schön, wenn die Welt freundlich antwortet." }, ziel = { "%s, wie schön, wenn die Welt freundlich antwortet.", "%s: Heute ist ein guter Tag für ein Wiedersehen." } }
addon.localeData.deDE.generalTexts.GLARE = { gruppe = { "Ein Blick sollte als Warnung genügen.", "Überlegt Euch den nächsten Schritt gut." }, ziel = { "%s, überlegt Euch den nächsten Schritt gut.", "%s: Ein Blick sollte als Warnung genügen." } }
addon.localeData.deDE.generalTexts.GLOAT = { gruppe = { "Ich möchte nicht angeben. Aber das war großartig.", "Ein wenig Triumph sei mir vergönnt." }, ziel = { "%s, ein wenig Triumph sei mir vergönnt.", "%s: Ich möchte nicht angeben. Aber das war großartig." } }
addon.localeData.deDE.generalTexts.GOLFCLAP = { gruppe = { "Ein äußerst bescheidener Applaus erscheint angebracht.", "Das war immerhin ein Versuch." }, ziel = { "%s, das war immerhin ein Versuch.", "%s: Ein äußerst bescheidener Applaus erscheint angebracht." } }
addon.localeData.deDE.generalTexts.GRIN = { gruppe = { "Mir kommt gerade eine vergnügliche Idee.", "Dieses Lächeln verrät garantiert nichts." }, ziel = { "%s, dieses Lächeln verrät garantiert nichts.", "%s: Mir kommt gerade eine vergnügliche Idee." } }
addon.localeData.deDE.generalTexts.GROAN = { gruppe = { "Das wird ein wirklich langer Tag.", "Können wir die schlechten Ideen wenigstens zählen?" }, ziel = { "%s, können wir die schlechten Ideen wenigstens zählen?", "%s: Das wird ein wirklich langer Tag." } }
addon.localeData.deDE.generalTexts.GROVEL = { gruppe = { "Meine Würde ist heute überraschend preiswert.", "Wenn Demut hilft, beginne ich sofort." }, ziel = { "%s, wenn Demut hilft, beginne ich sofort.", "%s: Meine Würde ist heute überraschend preiswert." } }
addon.localeData.deDE.generalTexts.GUFFAW = { gruppe = { "Das war der beste Witz seit der letzten Schlacht!", "Darüber lache ich noch tagelang." }, ziel = { "%s, darüber lache ich noch tagelang.", "%s: Das war der beste Witz seit der letzten Schlacht!" } }
addon.localeData.deDE.generalTexts.HAPPY = { gruppe = { "Das Leben schenkt uns gerade einen guten Augenblick.", "Lasst uns diesen Tag nicht verstreichen." }, ziel = { "%s, lasst uns diesen Tag nicht verstreichen.", "%s: Das Leben schenkt uns gerade einen guten Augenblick." } }
addon.localeData.deDE.generalTexts.HEALME = { gruppe = { "Ich bin verwundet und nicht aus Stein!", "Ein Heiler wäre hier gerade Gold wert." }, ziel = { "%s, ein Heiler wäre hier gerade Gold wert.", "%s: Ich bin verwundet und nicht aus Stein!" } }
addon.localeData.deDE.generalTexts.HELPME = { gruppe = { "Ich brauche hier wirklich Unterstützung!", "Wer freie Hände hat, möge sich melden." }, ziel = { "%s, wer freie Hände hat, möge sich melden.", "%s: Ich brauche hier wirklich Unterstützung!" } }
addon.localeData.deDE.generalTexts.HUNGRY = { gruppe = { "Meine Gedanken kreisen nur noch ums Essen.", "Ein Eintopf wäre jetzt ein großer Sieg." }, ziel = { "%s, ein Eintopf wäre jetzt ein großer Sieg.", "%s: Meine Gedanken kreisen nur noch ums Essen." } }
addon.localeData.deDE.generalTexts.IMPATIENT = { gruppe = { "Meine Geduld hat gerade Urlaub genommen.", "Wenn wir noch warten, wächst hier Gras." }, ziel = { "%s, wenn wir noch warten, wächst hier Gras.", "%s: Meine Geduld hat gerade Urlaub genommen." } }
